32	  steps: Step[];
33	}
34	
35	export type StepResult = { premium: number } | { payout: number; remainingCap: number };
36	
37	export interface ScenarioResult {
38	  results: StepResult[];
39	}
40	
41	const PROCESSING_FEE = 5;
42	
43	const FIRST_INSURANCE_PERCENT = 10;
44	
45	const BASE_PREMIUMS: Record<string, number> = {
46	  sword: 100,
47	  amulet: 60,
48	  staff: 80,
49	  potion: 40,
50	  rune: 25,
51	};
52	
53	// Percentages MUST go through this helper. Applying them as exact integer
54	// fractions keeps the arithmetic drift-free; the tempting `amount * 1.1`
55	// yields 110.00000000000001 for 100, and since the spec rounds premiums UP
56	// at the very end that drift becomes a whole extra G.
57	const addPercent = (amount: number, percent: number): number =>
58	  (amount * (100 + percent)) / 100;
59	
60	const quote = ({ items }: QuoteStep): StepResult => {
61	  const policyBase = items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
62	  const withFirstInsurance = addPercent(policyBase, FIRST_INSURANCE_PERCENT);
63	
64	  return { premium: Math.ceil(withFirstInsurance + PROCESSING_FEE) };
65	};
66	
67	export const runScenario = (scenario: Scenario): ScenarioResult => ({
68	  // Only quote steps are exercised so far; claim dispatch arrives with its first test.
69	  results: scenario.steps.map((step) => quote(step as QuoteStep)),
70	});
